import { HttpClient } from '@angular/common/http';
import { Component } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { Pet } from 'src/app/Modele/Pet.model';
import { CommentService } from 'src/app/services/comment.service';
import { PetsService } from 'src/app/services/pets.service';


@Component({
  selector: 'app-pet',
  templateUrl: './pet.component.html',
  styleUrls: ['./pet.component.css']
})
export class PetComponent {

  PET: any[] = [];
  editingPet: Pet | null = null;
  filteredFishes:any[]=[];
  searchName:string='';

  registerForm:FormGroup;
  nameInput: FormControl;
  petType: FormControl;
  fact: FormControl;
  img_url: FormControl;



  constructor( private http:HttpClient ,private petsServie:PetsService,private commentService:CommentService){

 this.nameInput=new FormControl('', Validators.required);
 this.petType= new FormControl('', Validators.required);
 this.fact=new FormControl('', Validators.required);
 this.img_url= new FormControl('', Validators.required);

 this.registerForm=new FormGroup({

  name:this.nameInput,
  petType:this.petType,
  fact:this.fact,
  img_url:this.img_url,
 });

  }

  ngOnInit() {
    this.loadFishes(); 
  }




  onSubmit() {
    if (this.registerForm.valid) {
      if (this.editingPet) {

        this.onUpdate(this.editingPet);
      } else {

        const petData = this.registerForm.value;

        this.http.post('http://localhost:8080/pets/add', petData).subscribe(
          (response) => {
            console.log('Pet added successfully:', response);
            this.loadFishes(); 
            this.resetForm(); 
          },
          (error) => {
            console.error('Error adding pet:', error);
          }
        );
      }
    }
  }

  editPet(pet: Pet) {
    this.editingPet = pet; 
    this.registerForm.patchValue(pet); 
  }

  resetForm() {
    this.registerForm.reset();
    this.editingPet = null;
  }



search() {
  this.filteredFishes = this.Fishes.filter(fish =>
    fish.name.toLowerCase().includes(this.searchName.toLowerCase())
  );
}

  onUpdate(pet: Pet) {
    if (this.registerForm.valid) {
      const petData = this.registerForm.value;

      this.petsServie.updatePet(pet.name, petData).subscribe(
        (response) => {
          console.log('Pet updated successfully:', response);
          this.loadFishes(); 
          this.resetForm(); 
        },
        (error) => {
          console.error('Error updating pet:', error);
        }
      );
    }
  }





  onDelete(name: string) {
    this.petsServie.deletePet(name).subscribe(
      (response) => {
        console.log('Pet deleted successfully:', response);

        this.loadFishes();
      },
      (error) => {
        console.error('Error deleting pet:', error);
      }
    );
  }

  onLike(petId:number){
  }



  private loadFishes(){
    this.petsServie.getAllPets().subscribe(
      (data) => {
        this.Fishes = data;
      },
      (error) => {
        console.error('Error loading Fishes:', error);
      }
    );

  }



  }
<br>


<mat-form-field class="searchs">
  <input matInput type="text" [(ngModel)]="searchName" placeholder="Search by name">
</mat-form-field>
<button mat-raised-button class="primary" (click)="search()">Search</button>



<div *ngFor="let fish of filteredFishes" class="fish-card">
  <div class="fish-info">
    <img [src]="fish.img_url" alt="{{ fish.name }} Image" style="width: 300px;">
    <h3>{{ fish.name }}</h3>
    <p>Type: {{ fish.petType }}</p>
    <label><h3>Fact:</h3></label>
    <p>{{ fish.fact }}</p>
  </div>
  <div class="fish-actions">

    <button mat-raised-button color="primary" (click)="editPet(fish)">Edit</button>
    <button mat-raised-button color="warn" (click)="onDelete(fish.name)">Delete</button>
  </div>
</div>

<button (click)="resetForm()">Reset</button>



<div class="container mt-4">
  <form [formGroup]="registerForm" (ngSubmit)="onSubmit()">
    <div class="form-row">
      <div class="form-group col-md-6">
        <label for="name">Name:</label>
        <input type="text" class="form-control" id="name" formControlName="name" placeholder="Enter the pet name">
        <div *ngIf="nameInput.invalid && (nameInput.dirty || nameInput.touched)" class="text-danger">
          Name is required
        </div>
      </div>

      <div class="form-group col-md-6">
        <label for="petType">Pet Type:</label>
        <input type="text" class="form-control" id="petType" formControlName="petType" placeholder="Enter the pet type">
        <div *ngIf="petType.invalid && (petType.dirty || petType.touched)" class="text-danger">
          Pet Type is required.
        </div>
      </div>
    </div>

    <div class="form-row">
      <div class="form-group col-md-6">
        <label for="fact">Fact:  </label>
        <input type="text" class="form-control" id="fact" formControlName="fact" placeholder="Enter fact about your pet">
        <div *ngIf="fact.invalid && (fact.dirty || fact.touched)" class="text-danger">
          Fact is required.
        </div>
      </div>

      <div class="form-group col-md-6">
        <label for="img_url">Img URL:</label>
        <input type="text" class="form-control" id="img_url" formControlName="img_url" placeholder="Enter img for your pet">
        <div *ngIf="img_url.invalid && (img_url.dirty || img_url.touched)" class="text-danger">
          Img URL is required.
        </div>
      </div>
    </div>

    <button type="submit" class="btn btn-primary" [disabled]="registerForm.invalid">Add Pet</button>


 </form>



