<div class="row">
  <div class=" d-flex flex-wrap ">
    <div *ngFor="let fish of Fishes" class="col-sm-4 mb-4">
      <div class="card" style="width: 400px">
        <img [src]="fish.img_url" class="card-img-top" alt="{{ fish.name }} Image">
        <div class="card-body">
          <h5 class="card-title">{{ fish.name }}</h5>
          <p class="card-text">Type: {{ fish.petType }}</p>
          <ng-container *ngIf="fish.fact">
            <label><h3>Fact:</h3></label>
            <p *ngFor="let sentence of fish.fact.split('.'); let i = index">
              {{ sentence }}{{ i < fish.fact.split('.').length - 1 ? '.' : '' }}
            </p>
          </ng-container>
          <div class="fish-actions">
            <button (click)="editPet(fish)" class="btn btn-primary">Edit</button>
            <button (click)="onDelete(fish.name)" class="btn btn-danger">Delete</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
